package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 998244353

type Matrix [][]int

func matMul(a, b Matrix) Matrix {
	n := len(a)
	c := make(Matrix, n)
	for i := 0; i < n; i++ {
		c[i] = make([]int, n)
	}
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			for k := 0; k < n; k++ {
				c[i][j] = (c[i][j] + a[i][k]*b[k][j]) % MOD
			}
		}
	}
	return c
}

func matPow(mat Matrix, power int) Matrix {
	n := len(mat)
	result := make(Matrix, n)
	for i := 0; i < n; i++ {
		result[i] = make([]int, n)
		result[i][i] = 1
	}
	base := mat
	for power > 0 {
		if power%2 == 1 {
			result = matMul(result, base)
		}
		base = matMul(base, base)
		power /= 2
	}
	return result
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(reader, &n, &m)
	words := make([]string, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(reader, &words[i])
	}

	// Create a map from word to index
	wordIndex := make(map[string]int)
	for i, word := range words {
		wordIndex[word] = i
	}

	// Create adjacency matrix
	adj := make(Matrix, n)
	for i := 0; i < n; i++ {
		adj[i] = make([]int, n)
	}

	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			// Check if the suffix of words[i] matches the prefix of words[j]
			s1 := words[i]
			s2 := words[j]
			maxLen := len(s1)
			if len(s2) < maxLen {
				maxLen = len(s2)
			}
			for l := maxLen; l > 0; l-- {
				if s1[len(s1)-l:] == s2[:l] {
					adj[i][j] = 1
					break
				}
			}
		}
	}

	// Compute adj^m using matrix exponentiation
	resultMat := matPow(adj, m)

	// Sum all elements in the matrix
	total := 0
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			total = (total + resultMat[i][j]) % MOD
		}
	}

	fmt.Println(total)
}
