package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 998244353

type matrix [][]int

func matMul(a, b matrix) matrix {
	n := len(a)
	m := len(b[0])
	k := len(b)
	c := make(matrix, n)
	for i := 0; i < n; i++ {
		c[i] = make([]int, m)
		for j := 0; j < m; j++ {
			for l := 0; l < k; l++ {
				c[i][j] = (c[i][j] + a[i][l]*b[l][j]) % MOD
			}
		}
	}
	return c
}

func matPow(mat matrix, power int) matrix {
	n := len(mat)
	result := make(matrix, n)
	for i := 0; i < n; i++ {
		result[i] = make([]int, n)
		result[i][i] = 1
	}
	for power > 0 {
		if power%2 == 1 {
			result = matMul(result, mat)
		}
		mat = matMul(mat, mat)
		power /= 2
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(in, &n, &m)
	words := make([]string, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &words[i])
	}

	// Build adjacency list for transitions
	// Each state is a word index (0..n-1)
	// Transition from word i to word j if the last character of word i equals the first character of word j
	adj := make([][]int, n)
	for i := 0; i < n; i++ {
		lastChar := words[i][len(words[i])-1]
		for j := 0; j < n; j++ {
			if words[j][0] == lastChar {
				adj[i] = append(adj[i], j)
			}
		}
	}

	// Build transition matrix
	mat := make(matrix, n)
	for i := 0; i < n; i++ {
		mat[i] = make([]int, n)
		for _, j := range adj[i] {
			mat[i][j] = 1
		}
	}

	// Compute mat^(m-1)
	if m == 1 {
		fmt.Println(n)
		return
	}
	resultMat := matPow(mat, m-1)

	// Sum all elements in the matrix
	total := 0
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			total = (total + resultMat[i][j]) % MOD
		}
	}
	fmt.Println(total)
}
